export const BODY: string = "\n<p>سرحد تصویر کے گرد فریم ہے۔ یہ تصویر کو اس کے اردگرد سے الگ کرتی ہے، تکمیلی لمس دیتی ہے، اور تصویر کو مکمل ہونے کا احساس دیتی ہے۔</p>\n<p>سرحدیں فوٹوگرافی کے آغاز سے اس کا حصہ ہیں۔ پرنٹ کارڈ پر لگائے جاتے تھے، سلائیڈ فریم میں رکھی جاتی تھیں، اور آج ڈیجیٹل سرحد اسکرین پر وہی کام کرتی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ سرحدیں کیسے کام کرتی ہیں، کون سی طرزیں چنیں، اور انہیں اچھی طرح کیسے استعمال کریں۔ اس میں ٹھوس سرحدیں، پولرائڈ طرز، گریڈینٹ چمک فریم، سائے، اور رنگ انتخاب شامل ہیں۔</p>\n<h2 id=\"what-is-a-border\">تصویر کی سرحد کیا ہے؟</h2>\n<p>سرحد تصویر کے کناروں کے گرد رنگ یا نمونے کی پٹی ہے۔ یہ خود تصویر کے باہر بیٹھتی ہے، اس لیے وہ تصویر کے کسی بھی حصے کو نہیں ڈھکتی۔</p>\n<p>سرحدیں دو مقصد پورے کرتی ہیں۔ وہ تصویر کو سجاتی ہیں، اسے تیار شکل دیتی ہیں، اور اسے پس منظر سے الگ کرتی ہیں، جس سے وہ مصروف صفحے پر نمایاں ہوتی ہے۔</p>\n<p>سرحد کراپ سے مختلف ہے۔ کراپ کناروں سے پکسل ہٹاتا ہے، جبکہ سرحد ان کے گرد پکسل شامل کرتی ہے، حتمی تصویر کو تھوڑا بڑا بناتے ہوئے۔</p>\n<h2 id=\"solid-borders\">ٹھوس سرحدیں: کلاسک فریم</h2>\n<p>ٹھوس سرحد تصویر کے گرد ایک رنگ کی برابر چوڑائی والی پٹی ہے۔ یہ سب سے آسان طرز ہے، اور یہ تقریباً کسی بھی تصویر کو سوٹ کرتی ہے، پورٹریٹ سے لے کر مصنوعات شاٹ تک۔</p>\n<p>سفید سرحدیں سب سے عام ہیں۔ وہ تصویر کو صاف، گیلری احساس دیتی ہیں، اور کسی بھی پس منظر پر کام کرتی ہیں، کیونکہ سفید تصویر کو صفحے سے الگ کرتا ہے۔</p>\n<p>کالی سرحدیں زیادہ ڈرامائی لگتی ہیں۔ وہ مزاجی تصویروں، رات کے شاٹ اور فائن آرٹ کو سوٹ کرتی ہیں، جہاں گہرا فریم تصویر میں وزن اور توجہ بڑھاتا ہے۔</p>\n<h2 id=\"polaroid-style\">پولرائڈ طرز: ریٹرو پسندیدہ</h2>\n<p>پولرائڈ سرحد فوری فلم شکل کی نقل کرتی ہے: نیچے موٹی پٹی والا سفید فریم۔ یہ پرانی یاد، آرام دہ اور تفریحی لگتی ہے، اسی لیے یہ چھٹی کی تصویروں اور یادوں کو سوٹ کرتی ہے۔</p>\n<p>نیچے والی موٹی پٹی طرز کی پہچان ہے۔ یہ ہاتھ سے لکھے کیپشن، تاریخ، یا مختصر نوٹ کے لیے جگہ دیتی ہے، بالکل اصلی پولرائڈ پرنٹ کی طرح۔</p>\n<p>پولرائڈ سرحدیں آرام دہ، ذاتی تصویروں پر بہترین کام کرتی ہیں۔ وہ رسمی پورٹریٹ یا مصنوعات شاٹ پر بے جگہ لگتی ہیں، جہاں صاف ٹھوس سرحد زیادہ مناسب ہے۔</p>\n<h2 id=\"gradient-glow\">گریڈینٹ چمک فریم</h2>\n<p>گریڈینٹ چمک فریم تصویر کے گرد دو یا زیادہ رنگ ملاتا ہے، نرم، چمکدار کنارہ بناتے ہوئے۔ یہ جدید اور ڈیجیٹل لگتا ہے، اور سوشل گرافکس اور پوسٹر کو سوٹ کرتا ہے۔</p>\n<p>چمک زاویہ اور رنگوں کے سیٹ سے حساب ہوتی ہے۔ زاویہ بدلنے سے ملاوٹ فریم کے گرد گھومتی ہے، اس لیے ایک ہی رنگ کئی مختلف شکلیں بنا سکتے ہیں۔</p>\n<p>گریڈینٹ فریم گہری تصویروں پر اچھا کام کرتے ہیں، جہاں روشن کنارہ توانائی بڑھاتا ہے۔ وہ ہلکی، ہوائی تصویر پر غالب آ سکتے ہیں، اس لیے انہیں اس وقت استعمال کریں جب تصویر کو ڈرامہ چاہیے۔</p>\n<h2 id=\"border-size\">سرحد سائز: 1% سے 25% تک</h2>\n<p>سرحد سائز تصویر کے فیصد کے طور پر طے ہوتا ہے، 1 فیصد سے 25 فیصد تک۔ چھوٹی سرحد پتلی لکیر ہے، جبکہ بڑی سرحد تصویر کے گرد چوڑا میٹ بن جاتی ہے۔</p>\n<p>1 سے 3 فیصد کی پتلی سرحد زیادہ تر تصویروں کو سوٹ کرتی ہے۔ یہ تصویر کو فریم کرتی ہے بغیر اس سے توجہ ہٹائے، اور کسی بھی دکھائی دینے والے سائز پر کام کرتی ہے۔</p>\n<p>5 سے 10 فیصد کی درمیانی سرحد گیلری احساس بناتی ہے۔ یہ تصویر کو سانس لینے کی جگہ دیتی ہے اور پرنٹ، پورٹ فولیو اور پریزنٹیشن سلائیڈ کو سوٹ کرتی ہے۔</p>\n<h2 id=\"frame-radius-vs-photo-radius\">فریم رداس بمقابلہ تصویر رداس</h2>\n<p>فریم رداس سرحد کے بیرونی کنارے کی گولائی کنٹرول کرتا ہے، جبکہ تصویر رداس اندرونی کنارے کی گولائی کنٹرول کرتا ہے جہاں سرحد تصویر سے ملتی ہے۔</p>\n<p>دونوں کو ایک ہی قیمت پر طے کرنے سے یکساں گول فریم ملتا ہے۔ انہیں مختلف طے کرنے سے ایسی سرحد بنتی ہے جو ہر طرف کے درمیان میں موٹی اور کونوں پر پتلی ہوتی ہے۔</p>\n<p>سادہ گول فریم کے لیے دونوں رداس ایک ہی عدد پر طے کریں۔ نتیجہ صاف، مستقل منحنی ہے جو کارڈ اور سوشل پوسٹ پر پیشہ ورانہ لگتا ہے۔</p>\n<h2 id=\"drop-shadows\">ڈراپ سائے: گہرائی شامل کرنا</h2>\n<p>ڈراپ سایہ فریم شدہ تصویر کے پیچھے نرم گہرا کنارہ شامل کرتا ہے، جس سے وہ صفحے کے اوپر تیرتی لگتی ہے۔ یہ گہرائی اور تکمیل کا احساس بڑھاتا ہے۔</p>\n<p>سائے ہلکے پس منظر پر بہترین کام کرتے ہیں، جہاں گہرا کنارہ نظر آتا ہے۔ گہرے پس منظر پر سایہ مل جاتا ہے اور تصویر میں کم شامل کرتا ہے۔</p>\n<p>ڈراپ سائے JPG کے طور پر برآمد کرنے پر غائب ہو جاتے ہیں۔ JPG فارمیٹ میں شفافیت نہیں، اس لیے سایہ، جسے دکھائی دینے کے لیے شفاف پس منظر چاہیے، اس فارمیٹ میں محفوظ نہیں ہو سکتا۔</p>\n<h2 id=\"colour-choices\">سرحد رنگ چننا</h2>\n<p>سفید محفوظ ترین سرحد رنگ ہے۔ یہ کسی بھی تصویر کو سوٹ کرتا ہے، کسی بھی پس منظر پر کام کرتا ہے، اور تصویر کو صاف، گیلری احساس دیتا ہے جو کبھی پرانا نہیں لگتا۔</p>\n<p>کالا دوسرا محفوظ ترین ہے۔ یہ ڈرامہ اور توجہ بڑھاتا ہے، اور مزاجی تصویروں، رات کے شاٹ اور فائن آرٹ کو سوٹ کرتا ہے، جہاں ہلکی سرحد بے جگہ لگے گی۔</p>\n<p>ڈیزائن شدہ شکل کے لیے سرحد کو تصویر کے رنگ سے ملائیں۔ لباس، آسمان یا مصنوعات کے رنگ کو اٹھانے والی سرحد فریم کو تصویر سے جوڑتی ہے۔</p>\n<h2 id=\"quick-frame-presets\">فوری فریم پری سیٹ</h2>\n<p>ٹول میں چار فوری فریم پری سیٹ ہیں، ہر ایک ایک کلک میں سرحد طرز، سائز، رنگ اور سایہ ترتیب دیتا ہے۔ وہ عام شکلوں کے لیے تیز نقطہ آغاز ہیں۔</p>\n<p>پری سیٹ مقفل نہیں ہیں۔ ایک کلک کرنے کے بعد آپ کوئی بھی ترتیب بدل سکتے ہیں، بشمول فریم رنگ، سائز یا سایہ، تاکہ وہ آپ کی تصویر کو سوٹ کرے۔</p>\n<p>طرزیں تیزی سے دریافت کرنے کے لیے پری سیٹ استعمال کریں۔ ان پر کلک کریں اور دیکھیں کون سی آپ کی تصویر کو سوٹ کرتی ہے، پھر وہاں سے ترتیبات باریک کریں۔</p>\n<h2 id=\"borders-for-social\">سوشل میڈیا کے لیے سرحدیں</h2>\n<p>سرحدیں تصویر کو بھیڑ والی فیڈ میں نمایاں ہونے میں مدد کرتی ہیں۔ سفید سرحد تصویر کو اس کے گرد پوسٹوں سے الگ کرتی ہے، اور آنکھ فریم شدہ تصویر کی طرف کھنچتی ہے۔</p>\n<p>سوشل سرحدیں پتلی رکھیں۔ موٹی سرحد چھوٹے فیڈ پیش نظارے میں جگہ لیتی ہے، تصویر کے لیے کم جگہ چھوڑتی ہے، جو لوگ دیکھنے آئے تھے۔</p>\n<p>اپنی پوسٹوں میں مستقل سرحد طرز استعمال کریں۔ پہچانا جانے والا فریم آپ کی بصری شناخت کا حصہ بن جاتا ہے، اور فالوور آپ کا نام پڑھنے سے پہلے آپ کی پوسٹیں پہچاننے لگتے ہیں۔</p>\n<h2 id=\"borders-for-print\">پرنٹ کے لیے سرحدیں</h2>\n<p>پرنٹ شدہ تصویروں نے ایک صدی سے زیادہ سرحدیں استعمال کی ہیں، اور ڈیجیٹل سرحد تصویر کو اسی سلوک کے لیے تیار کرتی ہے۔ پرنٹ کے گرد سفید سرحد اسے گیلری احساس دیتی ہے۔</p>\n<p>پرنٹ کے لیے 5 سے 10 فیصد کی درمیانی سرحد استعمال کریں۔ اضافی جگہ پرنٹ کو سانس لینے کی جگہ دیتی ہے، اور تصویر کو چھوئے بغیر سنبھالنے کے لیے مارجن دیتی ہے۔</p>\n<p>سرحد شامل کرنے سے پہلے پرنٹ سائز جانچیں۔ سرحد کل ابعاد بڑھاتی ہے، اس لیے سرحد والی تصویر کو بغیر سرحد والی اسی تصویر سے بڑے کاغذ سائز کی ضرورت ہوتی ہے۔</p>\n<h2 id=\"borders-for-products\">مصنوعات تصویروں کے لیے سرحدیں</h2>\n<p>مصنوعات تصویروں کو مستقل فریمنگ چاہیے، کیونکہ بے میل سرحدوں والا دکان صفحہ لاپرواہ لگتا ہے۔ ہر مصنوعات تصویر کے لیے ایک ہی سرحد طرز اور سائز استعمال کریں۔</p>\n<p>پتلی سفید سرحد زیادہ تر مصنوعات کو سوٹ کرتی ہے۔ یہ چیز کو صفحہ پس منظر سے الگ کرتی ہے بغیر مصنوعات سے توجہ ہٹائے۔</p>\n<p>مصنوعات تصویروں پر رنگ والی سرحدوں سے بچیں جب تک رنگ آپ کے برانڈ کا حصہ نہ ہو۔ روشن فریم مصنوعات سے ٹکرا سکتا ہے اور لسٹنگ کو غیر پیشہ ورانہ بنا سکتا ہے۔</p>\n<h2 id=\"transparency-and-formats\">شفافیت، فارمیٹ اور برآمد</h2>\n<p>ٹول پیش نظارے میں فریم کے گرد سرمئی اور سفید چیکر بورڈ دکھاتا ہے۔ وہ نمونہ شفافیت کا مطلب ہے، سرمئی پس منظر نہیں، اور یہ دکھاتا ہے کہ تصویر کہاں دیکھنے والی ہے۔</p>\n<p>PNG یا WebP کے طور پر برآمد کرنے سے شفافیت محفوظ رہتی ہے، بشمول گول کونے اور ڈراپ سائے۔ JPG کے طور پر برآمد کرنے سے سب کچھ ٹھوس پس منظر پر چپٹا ہو جاتا ہے۔</p>\n<p>گول کونوں والی فریم شدہ تصویر کے لیے PNG یا WebP چنیں۔ JPG برآمد شفاف کونوں کو ٹھوس رنگ سے بھر دیتی ہے، جو گول شکل توڑ دیتی ہے۔</p>\n<h2 id=\"borders-vs-frames-vs-matting\">سرحدیں، فریم اور میٹنگ: کیا فرق ہے؟</h2>\n<p>سرحد تصویر کے گرد رنگ کی پٹی ہے، ڈیجیٹل طور پر شامل کی گئی۔ فریم جسمانی چیز ہے جو پرنٹ رکھتی ہے، اور میٹنگ فریم کے اندر کارڈ ہے جو پرنٹ کو گھیرتا ہے۔</p>\n<p>ڈیجیٹل سرحدیں میٹنگ کی نقل کرتی ہیں۔ تصویر کے گرد چوڑی سفید سرحد میٹ شدہ پرنٹ جیسی لگتی ہے، اسی لیے وہ گیلری سیاق میں گھر جیسی لگتی ہے۔</p>\n<p>پتلی سرحد فریم کنارے کے قریب ہے۔ یہ تصویر کی حد طے کرتی ہے بغیر وہ فراخ جگہ شامل کیے جو میٹنگ دیتی ہے۔</p>\n<h2 id=\"privacy-local-processing\">رازداری: اپ لوڈ کیے بغیر فریمنگ</h2>\n<p>تمام سرحد کام آپ کے براؤزر میں ہوتا ہے۔ آپ کی تصویریں کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو اہم ہے جب تصویریں ذاتی ہوں، کلائنٹ کام ہوں، یا غیر جاری شدہ مصنوعات ہوں۔</p>\n<p>یہ کلاؤڈ ایڈیٹر پر حقیقی فائدہ ہے۔ مصنوعات تصویر یا خاندانی پورٹریٹ کو صرف فریم شامل کرنے کے لیے ایسے سرور پر نہیں جانا چاہیے جسے آپ دیکھ نہیں سکتے۔</p>\n<p>ٹول برآمد پر EXIF GPS ڈیٹا بھی ہٹاتا ہے۔ ٹول سے ڈاؤن لوڈ شدہ فریم شدہ تصویر میں کوئی ریکارڈ نہیں کہ وہ کہاں لی گئی تھی۔</p>\n<h2 id=\"common-border-mistakes\">عام سرحد غلطیاں</h2>\n<p>سب سے عام غلطی بہت موٹی سرحد ہے۔ بھاری فریم چھوٹی تصویر پر غالب آتا ہے اور خود تصویر کے لیے کم جگہ چھوڑتا ہے، جو لوگ دیکھنے آئے تھے۔</p>\n<p>دوسری غلطی تصویر سے ٹکرانے والا رنگ ہے۔ نرم، دھیمی تصویر پر روشن سرحد توجہ کے لیے تصویر سے لڑتی ہے اور پورا ڈیزائن غلط دکھاتی ہے۔</p>\n<p>لوگ یہ بھی بھول جاتے ہیں کہ سرحد کل سائز بڑھاتی ہے۔ 25 فیصد سرحد والی تصویر اصل سے کہیں بڑی ہے، اور وہ اپنی منزل میں فٹ نہ ہو۔</p>\n<p>قدم بہ قدم عمل کے لیے <a href=\"/ur/blog/tasveer-par-border-kaise-lagayein/\">How to Add a Border to an Image</a> دیکھیں۔ طرز خیالات کے لیے <a href=\"/ur/blog/tasveer-frames-borders-styles/\">Image Frames and Borders: Styles for Social and Print</a> پڑھیں، اور فریم شدہ تصویر کے کونے گول کرنے کے لیے <a href=\"/ur/tasveer-ke-kone-gol-karein/\">Round Image Corners ٹول</a> آزمائیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویر کے لیے بہترین سرحد رنگ کون سا ہے؟","answer":"سفید محفوظ ترین انتخاب ہے: یہ کسی بھی تصویر کو سوٹ کرتا ہے، کسی بھی پس منظر پر کام کرتا ہے، اور صاف گیلری احساس دیتا ہے۔ کالا مزاجی یا رات کی تصویروں کے لیے ڈرامہ بڑھاتا ہے۔ ڈیزائن شدہ شکل کے لیے سرحد کو تصویر کے رنگ سے ملائیں، اور سنجیدہ تصویروں پر روشن رنگوں سے بچیں۔"},{"question":"کیا سرحد شامل کرنے سے میری تصویر کا سائز بدلتا ہے؟","answer":"جی ہاں۔ سرحد تصویر کے گرد پکسل شامل کرتی ہے، اس لیے حتمی تصویر اصل سے بڑی ہوتی ہے۔ ہر طرف 10 فیصد سرحد چوڑائی اور اونچائی میں 20 فیصد بڑھاتی ہے۔ سائز حد والی پلیٹ فارم پر اپ لوڈ سے پہلے حتمی ابعاد جانچیں۔"},{"question":"JPG کے طور پر برآمد کرنے کے بعد میرا ڈراپ سایہ کیوں غائب ہو گیا؟","answer":"JPG میں شفافیت نہیں، اور ڈراپ سائے کو دکھائی دینے کے لیے شفاف پس منظر چاہیے۔ اس کی بجائے PNG یا WebP کے طور پر برآمد کریں، جو دونوں شفافیت سپورٹ کرتے ہیں اور سایہ رکھتے ہیں۔ پیش نظارہ چیکر بورڈ دکھاتا ہے کہ تصویر کہاں شفاف ہے۔"},{"question":"پولرائڈ سرحد اور ٹھوس سرحد میں کیا فرق ہے؟","answer":"پولرائڈ سرحد میں نیچے موٹی پٹی ہوتی ہے، فوری فلم کی نقل کرتے ہوئے، کیپشن کے لیے جگہ کے ساتھ۔ ٹھوس سرحد چاروں طرف ایک رنگ کی برابر پٹی ہے۔ پولرائڈ آرام دہ تصویروں کو سوٹ کرتا ہے، جبکہ ٹھوس سرحدیں تقریباً کسی بھی چیز کو سوٹ کرتی ہیں۔"},{"question":"کیا فون پر تصویر پر سرحد شامل کر سکتا ہوں؟","answer":"جی ہاں۔ سرحد جنریٹر فون براؤزر میں کام کرتا ہے: اپنی گیلری سے اپ لوڈ کریں، طرز اور سائز چنیں، فریم کا پیش نظارہ دیکھیں، اور نتیجہ ڈاؤن لوڈ کریں۔ فوری پری سیٹ چھوٹی اسکرین پر سیکنڈوں میں تصویر فریم کرنا آسان بناتے ہیں۔"},{"question":"کیا مصنوعات تصویروں پر سرحدیں ہونی چاہییں؟","answer":"پتلی سفید سرحد عام طور پر مدد کرتی ہے، کیونکہ یہ مصنوعات کو صفحے سے الگ کرتی ہے اور لسٹنگ کو صاف دکھاتی ہے۔ پورے کیٹلاگ میں طرز ایک جیسی رکھیں۔ رنگ والی سرحدوں سے بچیں جب تک رنگ آپ کے برانڈ کا حصہ نہ ہو۔"}];
